insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000001', '00000000-0000-4000-8000-00000000c0de', 'Seyahat', 'public', '[{"id": "a1-airport", "word": "airport", "pos": "n", "level": "A1", "tr": ["havaalanı", "havalimanı"], "example_en": "Is the airport far from here?", "example_tr": "Havaalanı buradan uzak mı?"}, {"id": "a2-passport", "word": "passport", "pos": "n", "level": "A2", "tr": ["pasaport"], "example_en": "Where is my passport?", "example_tr": "Pasaportum nerede?"}, {"id": "a1-ticket", "word": "ticket", "pos": "n", "level": "A1", "tr": ["bilet"], "example_en": "I have a train ticket.", "example_tr": "Tren biletim var."}, {"id": "a2-luggage", "word": "luggage", "pos": "n", "level": "A2", "tr": ["bagaj"], "example_en": "We have too much luggage.", "example_tr": "Çok fazla bagajımız var.", "note": "Sayılmaz: ''two luggages'' denmez; ''two bags'' denir."}, {"id": "a1-hotel", "word": "hotel", "pos": "n", "level": "A1", "tr": ["otel"], "example_en": "This is a very good hotel.", "example_tr": "Burası çok iyi bir otel."}, {"id": "a2-journey", "word": "journey", "pos": "n", "level": "A2", "tr": ["yolculuk", "seyahat"], "example_en": "Have a good journey!", "example_tr": "İyi yolculuklar!", "note": "''trip'' daha kısadır; ''journey'' tek yön gidişi de anlatır."}, {"id": "b1-destination", "word": "destination", "pos": "n", "level": "B1", "tr": ["varış noktası", "gidilecek yer"], "example_en": "We finally arrived at our destination.", "example_tr": "Sonunda varış noktamıza ulaştık."}, {"id": "a2-flight", "word": "flight", "pos": "n", "level": "A2", "tr": ["uçuş"], "example_en": "Our flight was very good.", "example_tr": "Uçuşumuz çok iyiydi."}, {"id": "a2-delay", "word": "delay", "pos": "n", "level": "A2", "tr": ["rötar", "gecikme"], "example_en": "There is a two-hour delay.", "example_tr": "İki saatlik bir rötar var.", "senses": [{"pos": "v", "tr": ["geciktirmek", "ertelemek"], "example_en": "Rain will delay the train.", "example_tr": "Yağmur treni geciktirecek."}]}, {"id": "a2-abroad", "word": "abroad", "pos": "adv", "level": "A2", "tr": ["yurt dışında", "yurt dışına"], "example_en": "She wants to go abroad.", "example_tr": "Yurt dışına gitmek istiyor.", "note": "Önüne ''to'' gelmez: ''go to abroad'' değil, ''go abroad''."}, {"id": "a1-map", "word": "map", "pos": "n", "level": "A1", "tr": ["harita"], "example_en": "Do you have a city map?", "example_tr": "Şehir haritanız var mı?"}, {"id": "a2-reservation", "word": "reservation", "pos": "n", "level": "A2", "tr": ["rezervasyon"], "example_en": "I made a hotel reservation.", "example_tr": "Otel rezervasyonu yaptım."}, {"id": "a2-tourist", "word": "tourist", "pos": "n", "level": "A2", "tr": ["turist"], "example_en": "Many tourists visit here.", "example_tr": "Burayı çok turist ziyaret eder."}, {"id": "b1-border", "word": "border", "pos": "n", "level": "B1", "tr": ["sınır"], "example_en": "We passed the border at night.", "example_tr": "Sınırı gece geçtik."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000002', '00000000-0000-4000-8000-00000000c0de', 'İş toplantısı', 'public', '[{"id": "a2-meeting", "word": "meeting", "pos": "n", "level": "A2", "tr": ["toplantı"], "example_en": "We have an important meeting.", "example_tr": "Önemli bir toplantımız var."}, {"id": "a2-deadline", "word": "deadline", "pos": "n", "level": "A2", "tr": ["son teslim tarihi"], "example_en": "The deadline is this Friday.", "example_tr": "Son teslim tarihi bu cuma."}, {"id": "a2-colleague", "word": "colleague", "pos": "n", "level": "A2", "tr": ["iş arkadaşı"], "example_en": "I eat lunch with my colleagues.", "example_tr": "Öğle yemeğini iş arkadaşlarımla yerim."}, {"id": "b2-proposal", "word": "proposal", "pos": "n", "level": "B2", "tr": ["teklif", "öneri"], "example_en": "I will read your proposal tomorrow morning.", "example_tr": "Teklifinizi yarın sabah okuyacağım."}, {"id": "b1-budget", "word": "budget", "pos": "n", "level": "B1", "tr": ["bütçe"], "example_en": "My budget is very small.", "example_tr": "Bütçem çok dar.", "senses": [{"pos": "v", "tr": ["bütçe yapmak"], "example_en": "We need to budget our money.", "example_tr": "Bütçe yapmamız lazım."}]}, {"id": "b2-negotiate", "word": "negotiate", "pos": "v", "level": "B2", "tr": ["pazarlık etmek", "görüşmek"], "example_en": "We must negotiate the price with the company.", "example_tr": "Şirketle fiyat konusunda pazarlık yapmalıyız."}, {"id": "b2-client", "word": "client", "pos": "n", "level": "B2", "tr": ["müşteri", "müvekkil"], "example_en": "The new client wants an important meeting.", "example_tr": "Yeni müşteri önemli bir toplantı istiyor."}, {"id": "a2-manager", "word": "manager", "pos": "n", "level": "A2", "tr": ["müdür", "yönetici"], "example_en": "The manager is in a meeting.", "example_tr": "Müdür toplantıda."}, {"id": "b1-contract", "word": "contract", "pos": "n", "level": "B1", "tr": ["sözleşme", "kontrat"], "example_en": "I didn''t accept the contract.", "example_tr": "Sözleşmeyi kabul etmedim."}, {"id": "b1-responsible", "word": "responsible", "pos": "adj", "level": "B1", "tr": ["sorumlu"], "example_en": "He is responsible for the team.", "example_tr": "Takımdan o sorumlu."}, {"id": "b1-decision", "word": "decision", "pos": "n", "level": "B1", "tr": ["karar"], "example_en": "It was a very difficult decision.", "example_tr": "Çok zor bir karardı."}, {"id": "b2-priority", "word": "priority", "pos": "n", "level": "B2", "tr": ["öncelik"], "example_en": "Our first priority is to make the client happy.", "example_tr": "İlk önceliğimiz müşteriyi mutlu etmektir."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000003', '00000000-0000-4000-8000-00000000c0de', 'Mutfak ve yemek', 'public', '[{"id": "a1-kitchen", "word": "kitchen", "pos": "n", "level": "A1", "tr": ["mutfak"], "example_en": "She is in the kitchen.", "example_tr": "O mutfakta."}, {"id": "a2-recipe", "word": "recipe", "pos": "n", "level": "A2", "tr": ["tarif", "yemek tarifi"], "example_en": "This recipe is very easy.", "example_tr": "Bu tarif çok kolay."}, {"id": "a2-boil", "word": "boil", "pos": "v", "level": "A2", "tr": ["kaynatmak", "haşlamak"], "example_en": "Boil the vegetables in water.", "example_tr": "Sebzeleri suda haşlayın."}, {"id": "a2-fry", "word": "fry", "pos": "v", "level": "A2", "tr": ["kızartmak"], "example_en": "I fry fish for dinner.", "example_tr": "Akşam yemeği için balık kızartırım."}, {"id": "a2-delicious", "word": "delicious", "pos": "adj", "level": "A2", "tr": ["lezzetli", "nefis"], "example_en": "This dish is really delicious!", "example_tr": "Bu yemek gerçekten nefis!"}, {"id": "a2-spicy", "word": "spicy", "pos": "adj", "level": "A2", "tr": ["baharatlı", "acılı"], "example_en": "Is this chicken spicy?", "example_tr": "Bu tavuk acılı mı?"}, {"id": "a2-bake", "word": "bake", "pos": "v", "level": "A2", "tr": ["fırında pişirmek"], "example_en": "We can bake bread at home.", "example_tr": "Evde ekmek pişirebiliriz."}, {"id": "a2-dish", "word": "dish", "pos": "n", "level": "A2", "tr": ["yemek", "tabak"], "example_en": "This is our best dish.", "example_tr": "En iyi yemeğimiz budur.", "note": "Hem yapılan yemek hem de servis tabağı demektir."}, {"id": "user-seed-whisk", "word": "whisk", "pos": "v", "level": "B1", "tr": ["çırpmak"], "example_en": "Whisk the eggs with a fork.", "example_tr": "Yumurtaları çatalla çırp."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000004', '00000000-0000-4000-8000-00000000c0de', 'Duygular', 'public', '[{"id": "b2-anxious", "word": "anxious", "pos": "adj", "level": "B2", "tr": ["endişeli", "kaygılı"], "example_en": "She is anxious about her new job.", "example_tr": "Yeni işi konusunda endişeli."}, {"id": "b2-grateful", "word": "grateful", "pos": "adj", "level": "B2", "tr": ["minnettar"], "example_en": "I am grateful for your support.", "example_tr": "Desteğinize minnettarım."}, {"id": "b1-jealous", "word": "jealous", "pos": "adj", "level": "B1", "tr": ["kıskanç"], "example_en": "He is a very jealous husband.", "example_tr": "O çok kıskanç bir koca."}, {"id": "b1-proud", "word": "proud", "pos": "adj", "level": "B1", "tr": ["gururlu"], "example_en": "I am very proud of my daughter.", "example_tr": "Kızımla çok gurur duyuyorum."}, {"id": "b2-ashamed", "word": "ashamed", "pos": "adj", "level": "B2", "tr": ["utanmış", "mahcup"], "example_en": "You should be ashamed of yourself.", "example_tr": "Kendinden utanmalısın."}, {"id": "b1-lonely", "word": "lonely", "pos": "adj", "level": "B1", "tr": ["yalnız"], "example_en": "I feel lonely when you travel.", "example_tr": "Sen seyahat ettiğinde yalnız hissediyorum.", "note": "Fiziksel tek başınalıktan ziyade duygusal yalnızlığı ifade eder."}, {"id": "b1-nervous", "word": "nervous", "pos": "adj", "level": "B1", "tr": ["gergin", "heyecanlı"], "example_en": "Are you nervous about the exam?", "example_tr": "Sınav için gergin misin?", "note": "Olumsuz anlamda heyecan veya stres için sıkça kullanılır."}, {"id": "b1-disappointed", "word": "disappointed", "pos": "adj", "level": "B1", "tr": ["hayal kırıklığına uğramış"], "example_en": "We were disappointed with the hotel.", "example_tr": "Otel bizi hayal kırıklığına uğrattı."}, {"id": "b1-confident", "word": "confident", "pos": "adj", "level": "B1", "tr": ["kendinden emin"], "example_en": "She is a very confident manager.", "example_tr": "O çok kendinden emin bir yönetici."}, {"id": "b1-embarrassed", "word": "embarrassed", "pos": "adj", "level": "B1", "tr": ["mahcup", "utanmış"], "example_en": "I felt very embarrassed yesterday.", "example_tr": "Dün çok utandım."}, {"id": "b1-curious", "word": "curious", "pos": "adj", "level": "B1", "tr": ["meraklı"], "example_en": "I was curious about their decision.", "example_tr": "Kararlarını merak ediyordum."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000005', '00000000-0000-4000-8000-00000000c0de', 'Film izlerken', 'link', '[{"id": "b1-actually", "word": "actually", "pos": "adv", "level": "B1", "tr": ["aslında"], "example_en": "He seems angry, but actually he is very friendly.", "example_tr": "Kızgın görünüyor ama aslında çok cana yakın.", "note": "''Şu an'' (aktüel) demek değildir; ''aslında'' demektir."}, {"id": "b2-deal", "word": "deal", "pos": "n", "level": "B2", "tr": ["anlaşma"], "example_en": "We made a great deal with our new partner.", "example_tr": "Yeni ortağımızla harika bir anlaşma yaptık."}, {"id": "b1-whatever", "word": "whatever", "pos": "conj", "level": "B1", "tr": ["her ne", "ne olursa"], "example_en": "I will support you whatever you do.", "example_tr": "Ne yaparsan yap seni destekleyeceğim.", "note": "''Ne … -ersen'' yapısı: whatever you do = ne yaparsan yap."}, {"id": "b1-trust", "word": "trust", "pos": "v", "level": "B1", "tr": ["güvenmek"], "example_en": "I don''t trust him.", "example_tr": "Ona güvenmiyorum.", "senses": [{"pos": "n", "tr": ["güven"], "example_en": "Trust is important in a relationship.", "example_tr": "İlişkide güven önemlidir."}]}, {"id": "a2-promise", "word": "promise", "pos": "v", "level": "A2", "tr": ["söz vermek"], "example_en": "I promise to be there on time.", "example_tr": "Vaktinde orada olacağıma söz veriyorum.", "senses": [{"pos": "n", "tr": ["söz"], "example_en": "Remember your promise.", "example_tr": "Verdiğin sözü hatırla."}]}, {"id": "b2-guilty", "word": "guilty", "pos": "adj", "level": "B2", "tr": ["suçlu"], "example_en": "They assume he is guilty.", "example_tr": "Onun suçlu olduğunu varsayıyorlar."}, {"id": "b1-rescue", "word": "rescue", "pos": "v", "level": "B1", "tr": ["kurtarmak"], "example_en": "They rescue animals after a storm.", "example_tr": "Fırtınadan sonra hayvanları kurtarıyorlar."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;
